/* Focused planning sheets, using the same model as Home and Plan. */
(function () {
    const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
    const money = n => new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n/100);
    const storage = flowStorage, id = () => crypto.randomUUID();
    const input = (label,name,value='',type='text',extra='') => `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
    const amount = (label,name,cents=0,extra='') => input(label,name,(cents/100).toFixed(2),'number',`step="0.01" min="0" required ${extra}`);
    const button = (label,action,extra='',cls='back-button') => `<button type="button" class="${cls}" data-tool="${action}" ${extra}>${label}</button>`;
    const help = text => `<p class="detail-help">${text}</p>`;
    const option = (value,label,current) => `<option value="${esc(value)}" ${value===current?'selected':''}>${esc(label)}</option>`;
    const categories = (p,current='Other',name='category') => `<label class="field">Category<select name="${name}">${[...new Set([...flowCategories(p),current])].map(c=>option(c,c,current)).join('')}</select></label>`;
    const dialog = document.createElement('dialog'); dialog.id='flow-tools-dialog';dialog.className='transaction-details-dialog flow-tools-dialog';dialog.setAttribute('aria-labelledby','flow-tools-title');document.body.append(dialog);
    let opened = null, ruleUndo = null, reconciliation = null;
    function read() {
        const snapshot = getFlowSnapshot();
        return { snapshot, p: snapshot.flowPlanning || defaultFlowPlanning(), tx: snapshot.transactions, accounts: snapshot.bankAccounts || [], rules: snapshot.categoryRules || [] };
    }
    function stamp() { return JSON.stringify(getFlowSnapshot()); }
    function features(s) { return s.p.features ||= flowFeatureDefaults(); }
    function estimate(s) { return paydayEstimate(s.p,s.accounts,s.tx); }
    function guard() {
        if (!opened || opened.owner !== storage.getItem('flow_user_id') || opened.stamp !== stamp() || opened.day !== flowToday()) throw new Error('Your data or the day changed. Close this sheet and reopen it before saving.');
    }
    function announce(text) {
        let node=document.querySelector('#flow-tools-status');
        if(!node){node=document.createElement('p');node.id='flow-tools-status';node.className='payday-message';node.setAttribute('role','status');document.querySelector('.main')?.append(node);}
        node.textContent=text;
    }
    function commit(s,text='Saved. Your plan has been updated.') {
        guard();
        const snapshot={...s.snapshot,flowPlanning:s.p,transactions:s.tx,categoryRules:s.rules};
        if (!validFlowPlanning(s.p) || s.tx.some(t=>!validFlowTransactionExtras(t))) throw new Error('Check the payment details, dates, and amounts before saving.');
        replaceFlowSnapshot(snapshot);
        dialog.close(); if(typeof flowDataChanged==='function')flowDataChanged();
        document.dispatchEvent(new CustomEvent('flow-transaction-updated',{detail:{tools:true}}));
        document.dispatchEvent(new Event('flow-planning-updated'));announce(text);render();
    }
    function sheet(title,body,submit=null,label='Save changes',state=null) {
        const s=state||read();opened={state:s,owner:storage.getItem('flow_user_id'),stamp:stamp(),day:flowToday()};
        dialog.innerHTML=`<div class="dialog-head"><h2 id="flow-tools-title" tabindex="-1">${esc(title)}</h2>${button('×','close','aria-label="Close"','icon-button')}</div><form id="flow-tools-form"><div class="tools-body">${body}</div><p class="form-message" role="alert"></p>${submit?`<div class="modal-actions"><button type="submit" class="save-button">${label}</button></div>`:`<div class="modal-actions">${button('Done','close')}</div>`}</form>`;
        dialog.querySelector('form').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;if(!submit||!form.reportValidity())return;try{guard();submit(new FormData(form),s,form);}catch(error){form.querySelector('.form-message').textContent=error.message||'Could not save. Your previous data is still saved.';}});
        if(!dialog.open)dialog.showModal();dialog.scrollTop=0;dialog.querySelector('h2').focus({preventScroll:true});return s;
    }
    function breakdown(e,p) {
        const rows=[['Selected available money',e.balanceCents],['Purchases not in that balance',-e.adjustmentsCents],['Unpaid bills',-e.billsCents],['Essentials still reserved',-e.essentialsCents],['Cushion',-e.cushionCents],['Goal reserves',-e.goalsCents],['Card repayment reserves',-e.cardsCents]];
        return `<div class="breakdown">${rows.map(([label,value])=>`<div><span>${label}</span><strong>${money(value||0)}</strong></div>`).join('')}<div class="breakdown-total"><span>Estimated flexible money</span><strong>${e.ready?money(e.leftCents):'Needs a check'}</strong></div></div>${help(`Essentials are already kept aside. Flexible money is for extra spending after those needs, through ${esc(p.payday.nextDate||'your planning date')}. Future pay and available credit are excluded.`)}${!e.ready?`<ul class="missing-plan">${e.missing.map(m=>`<li>${esc(m)}</li>`).join('')}</ul>`:''}`;
    }
    function freshness(s) {
        if(s.p.manualBalance)return `Available money confirmed by you on ${s.p.manualBalance.date}.`;
        const selected=s.accounts.filter(a=>s.p.selectedAccountIds.includes(a.id));
        return selected.map(a=>`${a.name}: ${a.bankUpdatedAt?'bank data '+new Date(a.bankUpdatedAt).toLocaleString():'bank balance date unavailable'}; retrieved ${new Date(a.retrievedAt).toLocaleString()}.`).join(' ')||'Choose spending money in setup.';
    }
    function purchase() {
        const s=read(),e=estimate(s);
        sheet('Can I spend this?',`${help('Try a purchase without changing your transactions or your plan.')}<div class="stack">${amount('Purchase amount','purchase',0,'min="0.01"')}${categories(s.p,'Other')}${input('Planned date','date',flowToday(),'date',`required min="${flowToday()}" max="${esc(s.p.payday.nextDate)}"`)}</div><div id="purchase-result" class="purchase-result" role="status" aria-live="polite">${e.ready?'Enter an amount to see its effect.':esc(e.missing.join(' · '))}</div>${help('Existing essentials can cover the relevant part of this purchase. The cushion stays untouched. Bank reporting delays and your plan’s assumptions still apply.')}`,null,'',s);
        const form=dialog.querySelector('form');
        const update=()=>{const out=dialog.querySelector('#purchase-result');try{guard();const v=new FormData(form),r=flowPurchasePreview(e,flowAmount(v.get('purchase')),String(v.get('category')),String(v.get('date')),flowToday(),s.p.payday.nextDate);out.innerHTML=`<p class="small-label">${r.shortfall?'This would leave a shortfall':'After this purchase'}</p><strong class="preview-amount">${money(r.afterCents)}</strong><p>${money(r.usesReserveCents)} covered by existing essentials · ${money(r.extraCents)} from flexible money.</p><small>This is a preview. No purchase has been recorded.</small>`;}catch(error){out.textContent=error.message;}};
        form.addEventListener('input',update);form.addEventListener('change',update);
    }
    function reconcile(start=true) {
        if(start){const s=read();reconciliation={state:s,stamp:stamp(),owner:storage.getItem('flow_user_id'),day:flowToday(),step:0};}
        const q=reconciliation,s=q.state;
        if(q.stamp!==stamp()||q.owner!==storage.getItem('flow_user_id')||q.day!==flowToday())throw new Error('Your plan changed. Reopen Check my plan.');
        let body='';
        if(q.step===0)body=`${help('Choose which cash accounts fund everyday spending. Savings outside this list stay outside the estimate.')}<div class="stack">${s.accounts.filter(a=>a.type==='depository'&&a.currency==='USD'&&a.availableCents!==null).map(a=>`<label class="choice"><input name="account" type="checkbox" value="${esc(a.id)}" ${s.p.selectedAccountIds.includes(a.id)?'checked':''}><span><strong>${esc(a.name)}</strong><small>${money(a.availableCents)} · cached</small></span></label>`).join('')||help('No connected cash balances available. You can use a confirmed amount on the next step.')}</div>`;
        if(q.step===1)body=`${help(esc(freshness(s)))}<label class="field">Available money source<select name="source">${option('bank','Selected cached bank balances',s.p.manualBalance?'manual':'bank')}${option('manual','Amount I confirm today',s.p.manualBalance?'manual':'bank')}</select></label>${input('Available amount from your bank today','balance',s.p.manualBalance?(s.p.manualBalance.cents/100).toFixed(2):'','number','step="0.01"')}<label class="toggle-label"><input type="checkbox" name="covered">My entered amount includes all posted payments currently shown in Flow for these spending accounts.</label>${help('Check this only after comparing those payments with your bank. Unreflected manual purchases can be deducted separately after this check. A manual amount replaces the selected bank totals.')}`;
        if(q.step===2){const e=estimate(s);body=`${help('Confirm only payments you checked in the available balance above. Bank records stay unchanged.')}<div class="stack">${e.bills.map((b,i)=>`<div><label class="choice"><input name="paid" type="checkbox" value="${esc(JSON.stringify([b.id,b.dueDate]))}"><span><strong>${esc(b.name)} · ${money(b.amountCents)}</strong><small>Due ${esc(b.dueDate)} · entire payment already reflected</small></span></label>${amount('Or total part paid and reflected','partial-'+i,flowFeatures(s.p).partialBills.find(x=>x.billId===b.id&&x.dueDate===b.dueDate)?.paidCents||0)}</div>`).join('')||help('No unpaid bills in this planning window.')}</div>${help('Leave unpaid or uncertain bills unchecked. Enter a paid part only if you checked its effect on available money. Add a missing bill in Plan.')}<div class="plain-list">${flowFeatures(s.p).adjustments.map(a=>{const t=s.tx.find(t=>flowTransactionKey(t)===a.transactionKey);return t?`<label class="choice"><input type="checkbox" name="stillUnreflected" value="${esc(a.id)}" checked><span>${esc(t.name)} is still NOT included in my balance</span></label>`:help('A deducted purchase was removed; its deduction will be cleared.');}).join('')}</div>`;}
        if(q.step===3)body=`${breakdown(estimate(s),s.p)}${help(esc(freshness(s)))}<label class="toggle-label"><input type="checkbox" name="checked" required>I checked my available money, bills, and set-asides.</label>`;
        sheet('Check my plan',`<p class="small-label">${['Spending accounts','Available money','Bills already paid','Your checked plan'][q.step]} · ${q.step+1} of 4</p>${body}${q.step?button('Back','reconcile-back'):''}`,(v)=>{
            if(q.step===0)s.p.selectedAccountIds=v.getAll('account').map(String);
            if(q.step===1){
                if(v.get('source')==='manual'){
                    s.p.manualBalance={cents:flowAmount(v.get('balance'),true),date:flowToday()};
                    if(v.get('covered'))s.p.manualBalance.covered=s.tx.filter(t=>t.status!=='pending'&&(t.source!=='bank'||s.accounts.some(a=>s.p.selectedAccountIds.includes(a.id)&&a.accountId===t.accountId&&a.bankConnectionId===t.bankConnectionId))).map(t=>({key:flowTransactionKey(t),fingerprint:flowTransactionStamp(t)}));
                }else{if(!s.p.selectedAccountIds.length)throw new Error('Choose a cash account or use an amount you confirm today.');s.p.manualBalance=null;}

            }
            if(q.step===2){
                const unpaid=estimate(s).bills,paid=new Set(v.getAll('paid').map(String));
                const f=features(s);f.partialBills=[];
                for(const [i,b] of unpaid.entries()){
                    if(paid.has(JSON.stringify([b.id,b.dueDate])))s.p=decideBillPayment(s.p,s.tx,s.accounts,b.id,b.dueDate,'manual');
                    else {const cents=flowAmount(v.get('partial-'+i));if(cents>b.amountCents)throw new Error('A paid part cannot exceed the bill.');if(cents)features(s).partialBills.push({id:id(),billId:b.id,dueDate:b.dueDate,paidCents:cents,balanceKey:flowBalanceKey(s.p,s.accounts)});}
                }
                const retained=new Set(v.getAll('stillUnreflected'));features(s).adjustments=f.adjustments.filter(a=>retained.has(a.id)).map(a=>{const t=s.tx.find(t=>flowTransactionKey(t)===a.transactionKey);return {...a,fingerprint:flowTransactionStamp(t),balanceKey:flowBalanceKey(s.p,s.accounts),confirmedOn:flowToday()};});
                s.p.billsConfirmed=true;
            }
            if(q.step===3){if(!v.get('checked'))throw new Error('Confirm your check first.');commit(s,'Your money check is saved. Any remaining questions are shown in your plan.');reconciliation=null;return;}
            q.step++;reconcile(false);
        },q.step===3?'Save my check':'Continue',s);
    }
    function adjustment() {
        const s=read(),f=flowFeatures(s.p),existing=new Set(f.adjustments.map(a=>a.transactionKey));
        const choices=s.tx.filter(t=>t.type==='Expense'&&t.amount<0&&t.date>=s.p.periodStartedOn&&!existing.has(flowTransactionKey(t))&&!flowCardAccount(t,s.accounts));
        sheet('Purchases not in your balance',`${help('Use this only for money you spent that is not yet deducted from the available amount in your plan. Do not deduct a payment twice.')}<div class="plain-list">${f.adjustments.map(a=>{const t=s.tx.find(t=>flowTransactionKey(t)===a.transactionKey);return `<div class="row-between"><span>${esc(t?.name||'Payment needs checking')}</span>${button('Remove deduction','remove-adjustment',`data-id="${esc(a.id)}"`)}</div>`;}).join('')}</div><label class="field">Purchase<select name="transaction" required><option value="">Choose a purchase</option>${choices.map(t=>option(t.id,`${t.name} · ${t.date} · ${money(-Math.round(t.amount*100))}`,'')).join('')}</select></label><label class="toggle-label"><input name="unreflected" type="checkbox" required>I checked that this purchase is not reflected in the plan’s available money.</label>`,(v,state)=>{const t=state.tx.find(t=>String(t.id)===v.get('transaction'));if(!t||!v.get('unreflected'))throw new Error('Choose and confirm an unreflected purchase.');features(state).adjustments.push({id:id(),transactionKey:flowTransactionKey(t),fingerprint:flowTransactionStamp(t),balanceKey:flowBalanceKey(state.p,state.accounts),confirmedOn:flowToday()});commit(state);},'Deduct this purchase',s);
    }
    function goal(goalId='') {
        const s=read(),savedGoal=flowFeatures(s.p).goals.find(g=>g.id===goalId),g=savedGoal?{...savedGoal,reservedCents:estimate(s).goals.find(x=>x.id===savedGoal.id)?.remainingCents??savedGoal.reservedCents}:null;
        sheet(g?'Edit your goal':'Give your money a purpose',`<div class="stack">${input('Goal name','name',g?.name||'','text','required maxlength="70" placeholder="For example, annual car insurance"')}${amount('Target amount','target',g?.targetCents||0,'min="0.01"')}${amount('Money already designated for this goal','reserved',g?.reservedCents||0)}${amount('Suggested amount each payday','contribution',g?.contributionCents||0)}${input('Target date · optional','dueDate',g?.dueDate||'','date')}<label class="field">Optional annual bill to fund<select name="billId"><option value="">A standalone goal</option>${s.p.bills.map(b=>option(b.id,b.name,g?.billId)).join('')}</select></label><label class="field">Where is the designated money?<select name="location">${option('inside','Within my selected spending money',g?.location||'inside')}${option('outside','In savings excluded from my spending money',g?.location)}</select></label><label class="toggle-label"><input name="locationChecked" type="checkbox" required>I checked where this money is held.</label></div>${help('Inside reserves reduce flexible money. Money already in excluded savings is tracked for progress and is not deducted again. This never moves money between banks. Link an annual bill to this goal to count the money once when the bill enters your payday window. Confirmed reflected payments consume the linked goal reserve.')}${g?button('Remove goal','delete-goal',`data-id="${esc(g.id)}"`):''}`,(v,state)=>{
            const next={id:g?.id||id(),name:String(v.get('name')).trim(),targetCents:flowAmount(v.get('target')),reservedCents:flowAmount(v.get('reserved')),contributionCents:flowAmount(v.get('contribution')),dueDate:String(v.get('dueDate')),location:String(v.get('location')),billId:String(v.get('billId')||''),coveredBillPayments:flowBillPaymentCoverage(state.p,getBillTrackingState(state.p,state.accounts,state.tx).rows,state.accounts)};
            if(!v.get('locationChecked'))throw new Error('Check the location of your goal money.');if(next.billId&&next.location!=='inside')throw new Error('Link a bill only to a fund inside your spending money.');if(next.billId&&flowFeatures(state.p).goals.some(x=>x.id!==next.id&&x.billId===next.billId))throw new Error('That bill already has a linked goal. Edit that fund instead.');const f=features(state);f.goals=f.goals.filter(x=>x.id!==next.id);f.goals.push(next);commit(state);
        },'Save goal',s);
    }
    function contribute(goalId) {
        const s=read(),savedGoal=flowFeatures(s.p).goals.find(g=>g.id===goalId),g=savedGoal?{...savedGoal,reservedCents:estimate(s).goals.find(x=>x.id===savedGoal.id)?.remainingCents??savedGoal.reservedCents}:null;if(!g)return;
        const e=estimate(s);
        sheet('Add to your goal',`${help(`<strong>${esc(g.name)}</strong> · ${money(g.reservedCents)} already designated of ${money(g.targetCents)}.`)}${amount('Amount to designate','amount',Math.min(g.contributionCents,Math.max(0,g.targetCents-g.reservedCents)))}${help(g.location==='inside'?`This reduces flexible money, currently ${e.ready?money(e.leftCents):'awaiting a plan check'}. It does not move money at your bank.`:'Confirm this money is already held in savings outside your selected spending accounts.')}<label class="toggle-label"><input type="checkbox" name="confirmed" required>I checked this contribution and its effect on my plan.</label>`,(v,state)=>{const n=flowAmount(v.get('amount'));if(n<=0)throw new Error('Enter a positive contribution.');const current=features(state).goals.find(x=>x.id===g.id);current.reservedCents=(estimate(state).goals.find(x=>x.id===g.id)?.remainingCents ?? current.reservedCents)+n;current.coveredBillPayments=flowBillPaymentCoverage(state.p,getBillTrackingState(state.p,state.accounts,state.tx).rows,state.accounts);if(!Number.isSafeInteger(current.reservedCents))throw new Error('This amount is too large.');commit(state,'Goal money updated. No bank transfer was made.');},'Designate money',s);
    }
    function card(cardId='') {
        const s=read(),savedCard=flowFeatures(s.p).cards.find(c=>c.id===cardId),c=savedCard?{...savedCard,reserveCents:estimate(s).cardReserves.find(x=>x.id===savedCard.id)?.remainingCents??savedCard.reserveCents}:null,cards=s.accounts.filter(a=>a.type==='credit'&&a.currency==='USD');
        if(!cards.length)return sheet('Card repayment planning',help('Connect a supported USD credit-card account to track its purchases and repayments. Available credit is never spending cash. You can reserve an unconnected card payment as a bill, but Flow cannot reconcile that card’s purchases.'),null,'',s);
        sheet('Plan a card repayment',`${help('Confirm money to keep aside for the card. New card purchases add to this reserve; posted refunds reduce it. Linked repayments release it only once reflected in selected cash.')}<div class="stack"><label class="field">Card<select name="accountId">${cards.map(a=>option(a.id,`${a.name} · reported debt ${a.currentCents===null?'unavailable':money(a.currentCents)}`,c?.accountId)).join('')}</select></label><label class="field">Repayment plan<select name="mode">${option('full','Reserve for the whole confirmed debt',c?.mode||'full')}${option('fixed','Reserve a chosen payment, plus new purchases',c?.mode)}${option('outside','This card is outside this spending plan',c?.mode)}</select></label>${amount('Repayment cash to reserve now','reserve',c?.reserveCents ?? Math.max(0,cards[0]?.currentCents||0))}${input('Payment due date','dueDate',c?.dueDate||s.p.payday.nextDate,'date','required')}<label class="toggle-label"><input type="checkbox" name="covered" required>This reserve accounts for all card activity already shown in Flow, including pending purchases. I checked it with my card provider.</label><label class="toggle-label"><input type="checkbox" name="essentialsChecked">Use posted purchases dated on this plan’s first day against essentials. I checked that those purchases belong to this reserve period.</label><label class="toggle-label"><input type="checkbox" name="noBill" required>This payment is not also reserved as a separate bill or goal.</label></div>${help('A chosen payment does not mean the debt is paid off. Choose outside only if you have accounted for any payment from your spending money as a bill. Full debt stays reserved even when its due date is later; a chosen payment is reserved when due in the current window. Newly arriving older activity asks for a new confirmation.')}${c?button('Remove repayment plan','delete-card',`data-id="${esc(c.id)}"`):''}`,(v,state)=>{
            const a=state.accounts.find(a=>a.id===v.get('accountId')&&a.type==='credit'&&a.currency==='USD');if(!a||!v.get('covered')||!v.get('noBill'))throw new Error('Choose a card and confirm both checks.');
            const f=features(state),next={id:c?.id||id(),accountId:a.id,mode:String(v.get('mode')),reserveCents:flowAmount(v.get('reserve')),confirmedOn:flowToday(),dueDate:String(v.get('dueDate')),essentialPeriodKey:flowReservePeriodKey(state.p),essentialCovered:v.get('essentialsChecked')?state.tx.filter(t=>flowCardAccount(t,[a])&&t.status!=='pending'&&t.date>=state.p.periodStartedOn).map(flowTransactionKey):(c?.essentialPeriodKey===flowReservePeriodKey(state.p)?c.essentialCovered||[]:[]),covered:state.tx.filter(t=>flowCardAccount(t,[a])).map(t=>({key:flowTransactionKey(t),amountCents:Math.round(t.amount*100),type:t.type,pendingId:t.pendingTransactionId||null}))};
            f.cards=f.cards.filter(x=>x.id!==next.id&&x.accountId!==next.accountId);f.cards.push(next);commit(state);
        },'Save repayment reserve',s);
    }
    function payments() {
        const s=read(),pairs=flowCardPaymentCandidates(s.tx,s.accounts);
        const linked=s.tx.filter(t=>t.cardPayment&&t.amount<0);
        sheet('Card payments between your accounts',`${help('Confirm only a checking payment that repaid your own credit card. Equal amounts alone do not prove a match. Original bank records remain separate.')}<div class="plain-list">${linked.map(t=>`<div><strong>${esc(t.name)} · ${money(-Math.round(t.amount*100))}</strong><p>${flowCardPeer(t,s.tx,s.accounts)?'Linked repayment':'Match needs a check after bank data changed'}</p>${button('Undo link','undo-card-payment',`data-id="${esc(t.id)}"`)}</div>`).join('')}${pairs.map(c=>`<div><strong>${esc(billCashAccount(c.debit,s.accounts).name)} → ${esc(flowCardAccount(c.credit,s.accounts).name)}</strong><p>${money(Math.round(c.credit.amount*100))} · ${esc(c.debit.date)} / ${esc(c.credit.date)}</p><p>${esc(c.debit.name)} / ${esc(c.credit.name)}</p>${button('Check this pair','confirm-card-payment',`data-debit="${esc(c.debit.id)}" data-credit="${esc(c.credit.id)}"`)}</div>`).join('')||help('No new posted pairs match the amount and date window. Bank reporting delays may leave one side missing.')}</div>`,null,'',s);
    }
    function transactionTools(transactionId) {
        const s=read(),t=s.tx.find(t=>String(t.id)===String(transactionId));if(!t)throw new Error('This transaction is no longer available.');
        const splits=t.allocations?.map(a=>`${money(a.cents)} ${a.category}`).join(' · ');
        sheet(t.name,`${help(`${money(Math.abs(Math.round(t.amount*100)))} · ${esc(t.date||'Date needed')}`)}${splits?help('Current split: '+esc(splits)):''}${t.allocationIssue?'<p class="notice-warning">The bank amount changed. Check this split before relying on its categories.</p>':''}<div class="tool-actions">${['Expense','Refund'].includes(t.type)&&!t.relatedExpense&&t.status!=='pending'?button('Split this payment','split',`data-id="${esc(t.id)}"`):''}${t.allocations?.length?button('Remove split','remove-split',`data-id="${esc(t.id)}"`):''}${t.amount>0&&t.type!=='Transfer'?button('Link refund / reimbursement','refund',`data-id="${esc(t.id)}"`):''}${t.relatedExpense?button('Remove reimbursement link','unlink-refund',`data-id="${esc(t.id)}"`):''}${t.cardPayment?button('Undo card payment link','undo-card-payment',`data-id="${esc(t.id)}"`):''}</div>${help('Splitting and linking organize the existing payment. They never change the original bank amount or create another transaction.')}`,null,'',s);
    }
    function split(transactionId) {
        const s=read(),t=s.tx.find(t=>String(t.id)===String(transactionId));if(!t)throw new Error('Reopen the payment.');
        const parts=t.allocations?.length?t.allocations:[{id:id(),category:t.category,cents:Math.abs(Math.round(t.amount*100))},{id:id(),category:'Other',cents:0}];
        const row=(a,i)=>`<div class="split-line" data-split-row>${categories(s.p,a.category,'category-'+i)}${amount('Amount','amount-'+i,a.cents)}${button('Remove','remove-split-row','aria-label="Remove this split part"','inline-link')}</div>`;
        sheet('Split one payment',`${help(`The parts must total ${money(Math.abs(Math.round(t.amount*100)))}.`)}<div id="split-lines">${parts.map(row).join('')}</div>${button('Add a part','add-split-row')}<p id="split-remaining" role="status"></p>`,(v,state,form)=>{
            const rows=[...form.querySelectorAll('[data-split-row]')].map((r,i)=>({id:'part-'+i,category:r.querySelector('select').value,cents:flowAmount(r.querySelector('input').value)}));
            state.tx=state.tx.map(x=>x.id===t.id?flowSplitTransaction(x,rows):x);commit(state,'Split saved. The original payment and total are unchanged.');
        },'Save split',s);
        const form=dialog.querySelector('form'),container=dialog.querySelector('#split-lines');
        const update=()=>{try{const total=[...container.querySelectorAll('input')].reduce((n,x)=>n+flowAmount(x.value),0);dialog.querySelector('#split-remaining').textContent=`${money(Math.abs(Math.round(t.amount*100))-total)} remaining to allocate`;}catch(_){dialog.querySelector('#split-remaining').textContent='Enter valid amounts for each part.';}};
        form.addEventListener('input',update);form.addEventListener('click',event=>{const a=event.target.closest('[data-tool]')?.dataset.tool;if(a==='add-split-row'){if(container.children.length>=30)return;container.insertAdjacentHTML('beforeend',row({category:'Other',cents:0},Date.now()));update();}if(a==='remove-split-row'){event.target.closest('[data-split-row]').remove();update();}});update();
    }
    function refund(transactionId) {
        const s=read(),t=s.tx.find(t=>String(t.id)===String(transactionId));if(!t)return;
        const expenses=s.tx.filter(x=>x.type==='Expense'&&x.amount<0&&x.status!=='pending');
        sheet('What does this repay?',`${help('Link received money to an expense, including a partial reimbursement. Expected money is never counted before it arrives.')}<label class="field">Original expense<select name="expense" required><option value="">Choose the expense</option>${expenses.map(x=>option(x.id,`${x.name} · ${x.date} · ${money(-Math.round(x.amount*100))}`,'')).join('')}</select></label>${amount('Amount of this deposit repaying the expense','amount',t.relatedExpense?.cents||Math.round(t.amount*100),'min="0.01"')}${help('Any remaining amount in this deposit remains income. The repayment reduces spending in the original categories; it does not create extra cash beyond the balance you use.')}`,(v,state)=>{state.tx=flowLinkRefund(state.tx,transactionId,String(v.get('expense')),flowAmount(v.get('amount')));commit(state);},'Link received money',s);
    }
    function categoryManager(categoryId='') {
        const s=read(),f=flowFeatures(s.p),c=f.categories.find(c=>c.id===categoryId);
        sheet(c?'Edit category':'Your categories',`${!c?`<div class="plain-list">${f.categories.map(c=>`<div class="row-between"><span>${esc(c.name)}${c.archived?' · archived':''}</span>${button('Manage','category',`data-id="${esc(c.id)}"`)}</div>`).join('')||help('Start with Flow’s defaults and add only categories that help you.')}</div>`:''}${input('Category name','name',c?.name||'','text','required maxlength="50"')}${c?`<label class="toggle-label"><input type="checkbox" name="archived" ${c.archived?'checked':''}>Archive from new choices, keeping existing records</label><label class="field">Or merge into an existing category<select name="merge"><option value="">Keep this category</option>${flowCategories(s.p,true).filter(x=>x!==c.name).map(x=>option(x,x,'')).join('')}</select></label>`:''}${help('Renaming or merging updates existing payments, split parts, rules, essentials, and category limits. You will review the affected count before saving.')}`,(v,state)=>{
            const name=String(v.get('name')).trim(),merge=String(v.get('merge')||''),f=features(state),newName=merge||name;
            if(!newName||newName.length>50)throw new Error('Choose a name up to 50 characters.');
            if(!merge&&flowCategories(state.p,true).some(x=>x.toLowerCase()===newName.toLowerCase()&&x!==c?.name))throw new Error('That category already exists.');
            if(c){
                const affected=state.tx.filter(t=>t.category===c.name||t.allocations?.some(a=>a.category===c.name)).length;
                if(newName!==c.name&&!confirm(`Update ${affected} payments and linked planning choices from ${c.name} to ${newName}?`))return;
                for(const t of state.tx){if(t.category===c.name)t.category=newName;for(const a of t.allocations||[])if(a.category===c.name)a.category=newName;}
                for(const r of state.rules)if(r.category===c.name)r.category=newName;
                const essentials=new Map();for(const e of state.p.essentials){const next={...e,category:e.category===c.name?newName:e.category};if(essentials.has(next.category))essentials.get(next.category).amountCents+=next.amountCents;else essentials.set(next.category,next);}state.p.essentials=[...essentials.values()];
                const changeLimits=rows=>{const map=new Map();for(const b of rows){const next={...b,category:b.category===c.name?newName:b.category};if(map.has(next.category))map.get(next.category).limit+=next.limit;else map.set(next.category,next);}return [...map.values()];};
                state.snapshot.budgets=changeLimits(state.snapshot.budgets);for(const month of Object.keys(state.snapshot.budgetsByMonth))state.snapshot.budgetsByMonth[month]=changeLimits(state.snapshot.budgetsByMonth[month]);
                f.categories=f.categories.filter(x=>x.id!==c.id);if(!merge)f.categories.push({...c,name,archived:Boolean(v.get('archived'))});
            }else f.categories.push({id:id(),name,archived:false});
            commit(state);
        },c?'Save category':'Add category',s);
    }
    function rules(ruleId='') {
        const s=read(),r=s.rules.find(r=>r.id===ruleId);
        if(!r)return sheet('Remembered choices',`${help('Individual corrections take priority. A paused rule stops matching new payments; existing choices stay in place.')}<div class="plain-list">${s.rules.map(r=>`<div><strong>${esc(r.label||r.name)}</strong><p>${esc(r.type)} → ${esc(r.bankType||r.category)}${r.accountId?' · one bank account':''}${r.paused?' · paused':''}</p>${button('Edit / preview','rule',`data-id="${esc(r.id)}"`)}</div>`).join('')||help('Remember a choice during Review to create an exact-name rule.')}</div>${ruleUndo?button('Undo last rule change','undo-rule'):''}`,null,'',s);
        const affected=s.tx.filter(t=>!t.allocations?.length&&(t.categoryRuleId===r.id||t.bankTypeRuleId===r.id));
        sheet('Review a remembered choice',`${help(`<strong>${esc(r.label||r.name)}</strong> · exact name, ${esc(r.type)}${r.accountId?' · same bank account and direction':''}.`)}${!r.bankType?categories(s.p,r.category):help('This is a confirmed transfer rule. Its ownership scope cannot be broadened here.')}<label class="toggle-label"><input type="checkbox" name="paused" ${r.paused?'checked':''}>Pause future matches</label>${!r.bankType?`<label class="toggle-label"><input name="existing" type="checkbox">Update ${affected.length} payments still assigned by this rule</label><details><summary>Preview affected payments</summary><ul>${affected.slice(0,20).map(t=>`<li>${esc(t.name)} · ${esc(t.date)} · ${esc(t.category)}</li>`).join('')||'<li>No existing automatic choices</li>'}</ul>${affected.length>20?help('First 20 shown; the affected count includes all.'):''}</details>`:''}${help('Individually chosen categories and split payments are preserved.')}`,(v,state)=>{
            const current=state.rules.find(x=>x.id===r.id),before=flowCopy(current),patches=[];
            current.paused=Boolean(v.get('paused'));if(!r.bankType)current.category=String(v.get('category'));
            if(v.get('existing')&&!r.bankType)for(const t of state.tx.filter(t=>t.categoryRuleId===r.id&&!t.allocations?.length)){patches.push({id:t.id,before:t.category,after:current.category});t.category=current.category;}
            ruleUndo={before,after:flowCopy(current),patches};commit(state,'Rule saved. You can undo this change from Remembered choices until you leave this page.');
        },'Save remembered choice',s);
    }
    function weekly() {
        const s=read(),summary=flowWeeklySummary(s.p,s.tx,s.accounts),e=estimate(s);
        sheet('A little weekly clarity',`<p class="small-label">${esc(summary.since)} – ${flowToday()}</p><div class="weekly-stats"><div><small>Posted spending, after refunds</small><strong>${money(summary.spendingCents)}</strong></div><div><small>Received income</small><strong>${money(summary.incomeCents)}</strong></div></div>${help(`${summary.questions} recent payments need a choice. Optional historical cleanup can wait.`)}${breakdown(e,s.p)}<label class="field">Anything to remember? · optional<textarea name="note" maxlength="500" rows="3">${esc(flowFeatures(s.p).checkIn?.note||'')}</textarea></label><label class="toggle-label"><input type="checkbox" name="reviewed" required>I checked my upcoming bills and current plan.</label>`,(v,state)=>{features(state).checkIn={date:flowToday(),note:String(v.get('note')).trim()};commit(state,'Weekly check-in saved. Your bills and balances were not changed.');},'Finish check-in',s);
    }
    function helpSheet() {
        const entries=[['What does the payday number mean?','It is estimated flexible money after unpaid bills, remaining essentials, cushion, goals, and card repayment reserves. Essentials are already set aside.'],['Why is a transfer missing?','Flow imports what your bank and Plaid make available. A recent completed transfer can arrive later. Checking again cannot force the bank to report it.'],['Why does a balance need checking?','A recent retrieval does not always mean the bank’s balance is recent. Use Check my plan to confirm available money without changing bank records.'],['Do I have to categorize old history?','No. Start with the current plan. Other still counts as spending. Use individual edits for mixed-purpose payments such as Venmo.'],['How do goals work?','Money reserved inside selected cash reduces flexible money. Savings already excluded from spending accounts is tracked without subtracting it again. No bank money is moved.'],['What happens offline?','Saved data stays on this device. Once Flow has loaded and prepared its offline copy, you can reopen cached screens. Bank checks and cloud sync need a connection.'],['How do I recover or leave?','Account offers cloud/device exports and conflict choices. Keep backups private. Signing out can clear this device’s Flow data; exports do not contain the server’s Plaid tokens.']];
        sheet('A quick guide to Flow',`<label class="field">Find help<input type="search" id="flow-help-search" placeholder="Try transfers, goals, or offline"></label><div id="flow-help-list">${entries.map(([title,text])=>`<details class="help-topic"><summary>${title}</summary><p>${text}</p></details>`).join('')}</div><a class="back-button" href="${typeof flowDemoMode!=='undefined'&&flowDemoMode?'setup.html':'demo/index.html'}">${typeof flowDemoMode!=='undefined'&&flowDemoMode?'Try setup with sample money':'Explore the sample workspace'}</a>`);
        dialog.querySelector('#flow-help-search').addEventListener('input',event=>{for(const entry of dialog.querySelectorAll('.help-topic'))entry.hidden=!entry.textContent.toLowerCase().includes(event.target.value.toLowerCase());});
    }
    function partialBill(billId,dueDate) {
        const s=read(),row=estimate(s).bills.find(b=>b.id===billId&&b.dueDate===dueDate);if(!row)throw new Error('This bill changed. Reopen Plan.');
        const prior=flowFeatures(s.p).partialBills.find(b=>b.billId===billId&&b.dueDate===dueDate);
        sheet('Part of a bill is paid',`${help(`${esc(row.name)} · ${money(row.amountCents)} expected on ${esc(dueDate)}.`)}${amount('Total already paid for this occurrence','paid',prior?.paidCents||0)}<label class="toggle-label"><input name="confirmed" type="checkbox" required>I checked that this paid amount is reflected in my available money.</label>${help('Only the unpaid remainder stays reserved. If your balance changes, Flow asks you to check this again. For an automatically tracked bank payment, use the existing Check bill flow when the full amount is settled.')}`,(v,state)=>{const n=flowAmount(v.get('paid'));if(n>row.amountCents)throw new Error('The paid amount cannot exceed this occurrence.');const f=features(state);f.partialBills=f.partialBills.filter(b=>!(b.billId===billId&&b.dueDate===dueDate));if(n)f.partialBills.push({id:prior?.id||id(),billId,dueDate,paidCents:n,balanceKey:flowBalanceKey(state.p,state.accounts)});commit(state);},'Save partial payment',s);
    }
    function billOccurrence(billId,dueDate) {
        const s=read(),b=s.p.bills.find(b=>b.id===billId);if(!b)throw new Error('This bill is no longer available.');
        const previous=flowBillOverride(b,dueDate);
        sheet('Change one bill occurrence',`${help(`<strong>${esc(b.name)}</strong> · due ${esc(dueDate)}. Future occurrences keep their usual schedule and amount.`)}${amount('Amount to reserve for this occurrence','amount',previous?.amountCents ?? billAmountAt(b,dueDate))}<label class="toggle-label"><input name="skip" type="checkbox" ${previous?.skipped?'checked':''}>This occurrence is not due · skip its reserve</label><label class="toggle-label"><input type="checkbox" name="checked" required>I checked this occurrence. Skipping is not the same as recording a payment.</label>${help('To change the next date or the whole schedule, use Edit bill in Plan. A skipped occurrence does not create a transaction.')}`,(v,state)=>{
            const current=state.p.bills.find(x=>x.id===b.id),cents=flowAmount(v.get('amount'));
            current.occurrenceOverrides=(current.occurrenceOverrides||[]).filter(o=>o.date!==dueDate);
            current.occurrenceOverrides.push({date:dueDate,amountCents:cents,skipped:Boolean(v.get('skip'))});
            commit(state,'This bill occurrence was updated. Future cycles keep their schedule.');
        },'Save occurrence',s);
    }
    function render() {
        if(!document.querySelector('.main'))return;
        let s,e;try{s=read();e=estimate(s);}catch(error){announce(error.message);return;}
        const f=flowFeatures(s.p),home=document.querySelector('#payday-home'),plan=document.querySelector('#payday-plan'),settings=document.querySelector('#payday-settings');
        if(home){
            home.querySelector('#flow-decision-tools')?.remove();
            const section=document.createElement('section');section.id='flow-decision-tools';section.className='card product-decision';
            section.innerHTML=`<div class="section-top"><div><p class="small-label">Make a decision</p><h3>Your money, explained.</h3></div>${button('Quick guide','help','','inline-link')}</div><p class="freshness-label">${esc(freshness(s))}</p><div class="tool-actions">${button('Can I spend this?','purchase','','save-button')}${button('Check my plan','reconcile')}${button('Weekly check-in','weekly')}</div>${help('Your essentials are already kept aside. The headline is the extra flexible money after those needs.')}<div class="tools-reminders">${flowReminderItems(s.p,e,s.accounts,s.tx).slice(0,3).map(r=>`<div class="reminder-row"><div><strong>${esc(r.title)}</strong><p>${esc(r.text)}</p></div>${button('Open',r.action)}${button('Tomorrow','snooze',`data-id="${esc(r.id)}"`,'inline-link')}</div>`).join('')}</div><div id="flow-change-summary"></div>`;
            home.querySelector('.payday-grid')?.after(section);
            if(!home.contains(section))home.append(section);
            let previous=null;try{previous=JSON.parse(storage.getItem('flowLastEstimate')||'null');}catch(_){}
            const current=flowEstimateSnapshot(s.p,e),changes=flowExplainChange(previous,current);
            if(changes.length)section.querySelector('#flow-change-summary').innerHTML=`<details><summary>What changed since your last saved view?</summary><ul>${changes.map(c=>`<li>${esc(c.label)}: ${c.deltaCents>=0?'+':''}${money(c.deltaCents)}</li>`).join('')}</ul>${help('These are changes to plan inputs, not a claim that every bank movement has been reconciled.')}</details>`;
            if(e.ready&&!document.hidden)try{storage.setItem('flowLastEstimate',JSON.stringify(current));}catch(_){/* A comparison snapshot is optional. */}
        }
        if(plan){
            plan.querySelector('#flow-plan-tools')?.remove();const tools=document.createElement('section');tools.id='flow-plan-tools';tools.className='product-tools-grid';
            tools.innerHTML=`<article class="card"><div class="section-top"><div><p class="small-label">For what matters</p><h3>Goals & annual costs</h3></div>${button('Add goal','goal','','inline-link')}</div><div class="plain-list">${(e.goals||f.goals).map(g=>`<div><div class="row-between"><strong>${esc(g.name)}</strong>${button('Edit','goal',`data-id="${esc(g.id)}"`,'inline-link')}</div><p>${money(g.remainingCents ?? g.reservedCents)} of ${money(g.targetCents)}${g.dueDate?' · '+esc(g.dueDate):''}</p><progress max="${g.targetCents}" value="${Math.min(g.remainingCents ?? g.reservedCents,g.targetCents)}" aria-label="${esc(g.name)} progress"></progress><small>${g.location==='inside'?'Reserved inside spending money':'Held in excluded savings'} · ${money(g.contributionCents)} suggested per payday</small>${button('Add to goal','contribute',`data-id="${esc(g.id)}"`)}</div>`).join('')||help('Plan for annual bills or a personal goal, with money designated each payday.')}</div></article><article class="card"><div class="section-top"><div><p class="small-label">Purchases and repayments</p><h3>Credit cards</h3></div>${button('Add card plan','card','','inline-link')}</div><div class="plain-list">${(e.cardReserves||[]).map(c=>`<div class="row-between"><span><strong>${esc(c.name)}</strong><small>${money(c.deductCents)} reserved now · ${c.mode==='full'?'full confirmed debt':'chosen payment + new purchases'}</small></span>${button('Check','card',`data-id="${esc(c.id)}"`)}</div>`).join('')||help('Credit limits are never cash. Plan card repayment money separately from spending.')}</div>${button('Match card payments','card-payments')}</article><article class="card"><p class="small-label">Keep the plan accurate</p><h3>Payments & organization</h3><div class="tool-actions">${button('Check my plan','reconcile')}${button('Unreflected purchases','adjustments')}${button('Custom categories','categories')}${button('Remembered choices','rules')}</div>${e.bills.length||s.p.bills.some(b=>b.occurrenceOverrides?.some(o=>o.skipped))?`<details><summary>Adjust a bill or record a partial payment</summary><div class="plain-list">${e.bills.map(b=>`<div class="row-between"><span>${esc(b.name)} · ${esc(b.dueDate)}</span>${button('Record paid part','partial-bill',`data-id="${esc(b.id)}" data-date="${esc(b.dueDate)}"`)}${button('Change this occurrence','bill-occurrence',`data-id="${esc(b.id)}" data-date="${esc(b.dueDate)}"`,'inline-link')}</div>`).join('')}${s.p.bills.flatMap(b=>(b.occurrenceOverrides||[]).filter(o=>o.skipped).map(o=>`<div class="row-between"><span>${esc(b.name)} · ${esc(o.date)} · skipped</span>${button('Restore / edit','bill-occurrence',`data-id="${esc(b.id)}" data-date="${esc(o.date)}"`)}</div>`)).slice(-12).join('')}</div></details>`:''}</article>`;plan.append(tools);
        }
        const setup=document.querySelector('#payday-setup');
        if(setup&&s.p.setup.step===5){setup.querySelector('#setup-card-plans')?.remove();if(s.accounts.some(a=>a.type==='credit'&&!f.cards.some(c=>c.accountId===a.id))){const cardNotice=document.createElement('section');cardNotice.id='setup-card-plans';cardNotice.className='card';cardNotice.innerHTML='<h3>One more choice for your card</h3>'+help('Choose repayment money before finishing the estimate. Available credit is never spending cash.')+button('Plan card repayment','card');setup.append(cardNotice);}}
        if(settings){
            settings.querySelector('#flow-product-settings')?.remove();const section=document.createElement('section');section.id='flow-product-settings';section.className='card account-card';section.innerHTML=`<p class="small-label">Make it yours</p><h3>Help & everyday tools</h3><div class="tool-actions">${button('Quick guide','help')}${button('Custom categories','categories')}${button('Remembered choices','rules')}${button('Weekly check-in','weekly')}</div><label class="toggle-label"><input type="checkbox" data-tools-preference="remindersEnabled" ${s.p.preferences.remindersEnabled?'checked':''}>Show useful reminders inside Flow</label><label class="toggle-label"><input type="checkbox" data-tools-preference="weeklyReminders" ${s.p.preferences.weeklyReminders?'checked':''}>Include a weekly check-in reminder</label><p class="detail-help">Reminders appear inside Flow. Snooze them from Home; no email or phone notifications are sent.</p><a href="${typeof flowDemoMode!=='undefined'&&flowDemoMode?'index.html':'demo/index.html'}" class="inline-link">Explore sample money</a>`;settings.append(section);
        }
    }
    document.addEventListener('click',event=>{
        const target=event.target.closest('[data-tool]');if(!target)return;const action=target.dataset.tool;
        if(['add-split-row','remove-split-row'].includes(action))return;
        try{
            if(action==='close')return dialog.close();
            const operations={purchase,reconcile,adjustments:adjustment,goal:()=>goal(target.dataset.id),contribute:()=>contribute(target.dataset.id),card:()=>card(target.dataset.id),'card-payments':payments,categories:categoryManager,category:()=>categoryManager(target.dataset.id),rules,rule:()=>rules(target.dataset.id),weekly,help:helpSheet,split:()=>split(target.dataset.id),refund:()=>refund(target.dataset.id),'partial-bill':()=>partialBill(target.dataset.id,target.dataset.date),'bill-occurrence':()=>billOccurrence(target.dataset.id,target.dataset.date)};
            if(operations[action])return operations[action]();
            if(action==='reconcile-back'){guard();reconciliation.step=Math.max(0,reconciliation.step-1);return reconcile(false);}
            if(action==='bills'){location.href='budgets.html#bill-tracking';return;}
            if(action==='payday-checkin'){document.querySelector('[data-plan-action="payday-checkin"]')?.click();return;}
            if(action==='snooze'){const s=read();opened={state:s,stamp:stamp(),owner:storage.getItem('flow_user_id'),day:flowToday()};const f=features(s);f.reminders=f.reminders.filter(r=>r.id!==target.dataset.id);f.reminders.push({id:target.dataset.id,until:addPlanDays(flowToday(),1)});return commit(s,'Reminder snoozed through tomorrow.');}
            guard();const s=opened.state;
            if(action==='remove-adjustment'){features(s).adjustments=features(s).adjustments.filter(a=>a.id!==target.dataset.id);return commit(s,'Deduction removed. Check that the purchase is reflected in your available balance.');}
            if(action==='delete-goal'||action==='delete-card'){if(!confirm('Remove this from your plan? Your bank records will remain unchanged.'))return;const f=features(s),key=action==='delete-goal'?'goals':'cards';f[key]=f[key].filter(x=>x.id!==target.dataset.id);return commit(s);}
            if(action==='confirm-card-payment'){if(!confirm('Did this checking payment repay this credit card you own? Only confirm after checking both records.'))return;s.tx=flowMatchCardPayment(s.tx,s.accounts,target.dataset.debit,target.dataset.credit);return commit(s,'Card repayment linked. The payment is not counted as another purchase.');}
            if(action==='undo-card-payment'){s.tx=flowUndoCardPayment(s.tx,target.dataset.id);return commit(s,'Link removed. Original bank amounts and your notes are unchanged.');}
            if(action==='remove-split'){const t=s.tx.find(t=>String(t.id)===target.dataset.id);delete t.allocations;delete t.allocationIssue;t.reviewStatus='reviewed';t.categoryReason='Chosen by you';return commit(s,'Split removed. The payment uses its single category again.');}
            if(action==='unlink-refund'){const t=s.tx.find(t=>String(t.id)===target.dataset.id),prior=t.relatedExpense;if(t.type==='Refund')t.type=prior.previousType||'Income';if(t.categoryReason==='Refund / reimbursement linked by you')t.category=prior.previousCategory||'Income';t.typeOverride=t.type!==(t.amount<0?'Expense':'Income');delete t.relatedExpense;delete t.allocations;delete t.allocationIssue;t.reviewStatus='reviewed';t.categoryReason='Chosen by you';return commit(s,'Reimbursement link removed. Check this payment’s type and category in its details.');}
            if(action==='undo-rule'&&ruleUndo){const r=s.rules.find(r=>r.id===ruleUndo.after.id);if(JSON.stringify(r)!==JSON.stringify(ruleUndo.after))throw new Error('The rule has changed again. Edit its latest version instead.');s.rules=s.rules.map(x=>x.id===r.id?flowCopy(ruleUndo.before):x);for(const patch of ruleUndo.patches){const t=s.tx.find(t=>t.id===patch.id);if(t?.categoryRuleId===r.id&&t.category===patch.after)t.category=patch.before;}ruleUndo=null;return commit(s,'Last rule change undone. Newer personal corrections were preserved.');}
        }catch(error){const box=dialog.open&&dialog.querySelector('.form-message');if(box)box.textContent=error.message;else announce(error.message);}
    });
    document.addEventListener('change',event=>{const key=event.target.dataset.toolsPreference;if(!['remindersEnabled','weeklyReminders'].includes(key))return;try{const s=read();opened={state:s,owner:storage.getItem('flow_user_id'),stamp:stamp(),day:flowToday()};s.p.preferences[key]=event.target.checked;commit(s,'Reminder preference saved.');}catch(error){event.target.checked=!event.target.checked;announce(error.message);}});
    dialog.addEventListener('click',event=>{if(event.target!==dialog)return;const b=dialog.getBoundingClientRect();if(event.clientX<b.left||event.clientX>b.right||event.clientY<b.top||event.clientY>b.bottom)dialog.close();});
    dialog.addEventListener('close',()=>{if(!dialog.open)opened=null;});
    for(const event of ['flow-payday-rendered','flow-transaction-view-refresh','flow-accounts-updated','flow-review-updated'])document.addEventListener(event,()=>{if(!dialog.open)render();});
    document.addEventListener('DOMContentLoaded',render);
    window.FlowTools={openTransaction:transactionTools,openPurchase:purchase,openReconciliation:reconcile,render};
    render();
})();
